(25, 'RNT-2021-025', 4, 23, NULL, '2021-07-01', '2022-06-30', 1, 500, 500, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario BBVA de los pisos (jul 2021 - ago 2026). Fianza devuelta por el IGVS el 18/08/2022 (500 €).'),
(26, 'RNT-2022-026', 4, 24, NULL, '2022-07-21', '2023-06-30', 1, 520, 520, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario BBVA de los pisos (jul 2021 - ago 2026). Transferencia de 1.225 € el 20/07/2022 = fianza 520 + agosto 520 + julio prorrateado 185. El 05/08/2022 llegó un segundo ingreso de 520 € (garantía adicional, no contabilizado como alquiler). Fianza devuelta por el IGVS el 17/07/2023 (520 €).'),
(27, 'RNT-2023-027', 4, 25, NULL, '2023-07-14', '2025-12-31', 1, 560, 560, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario BBVA de los pisos (jul 2021 - ago 2026). Transferencia de 1.445 € el 17/07/2023 = fianza 560 + garantía adicional 560 + julio prorrateado 325. Los 15 ingresos pequeños (97,95 € ... 152,30 €, unos 2.053 € en total) son reembolsos de suministros y no se contabilizan como alquiler. Fianza devuelta por el IGVS el 06/01/2026 (560 €).'),
(28, 'RNT-2026-028', 4, 26, NULL, '2026-01-01', NULL, 1, 590, 1120, TRUE, 'ACTIVE', TRUE, 'Importado del extracto bancario BBVA de los pisos (jul 2021 - ago 2026). Transferencia de 1.710 € el 31/12/2025 = fianza y depósito 1.120 € (ingresados en el IGVS ese mismo día, concepto «FIANZA Y DEPÓSITO 3º IZDA AVENIDA DO PASAXE») + enero 2026 590 €. El ingreso de 21,65 € del 26/01/2026 es un reembolso de suministros y no se contabiliza como alquiler.'),
(29, 'RNT-2023-029', 3, 27, 28, '2023-09-01', NULL, 1, 650, 650, FALSE, 'ACTIVE', TRUE, 'Importado del extracto bancario BBVA de los pisos (jul 2021 - ago 2026). De enero a noviembre de 2024 las mensualidades llegaron desde la cuenta de Jofer Fernando Ramírez Jáuregui (de agosto a noviembre de 2024 por 690,41 €, es decir 40,41 € por encima del alquiler). Fianza no localizada en el extracto (pendiente de confirmar).'),
(30, 'RNT-2021-030', 5, 29, NULL, '2021-06-01', '2022-02-28', 1, 500, 1000, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario ING de los pisos del 1º (may 2021 - ago 2026). Fianza 500 € ingresada en el IGVS el 12/06/2021 (garantía adicional de 500 € recibida el 30/06/2021). Diciembre de 2021 sin transferencia (posible pago en efectivo). El 05/04/2022 se le devolvieron 880 € (fianzas menos limpieza).'),
(31, 'RNT-2022-031', 5, 30, NULL, '2022-03-17', '2022-07-31', 1, 530, 530, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario ING de los pisos del 1º (may 2021 - ago 2026). Fecha de salida aproximada (pendiente de confirmar). Fianza 530 € ingresada en el IGVS el 11/04/2022 y devuelta por el IGVS el 06/08/2022. Mayo de 2022 sin transferencia; junio ingresado en efectivo («INGRESO 1 DCHA», 14/06/2022); abril (220 €) y julio (450 €) parciales.'),
(32, 'RNT-2022-032', 5, 31, 32, '2022-08-04', '2025-10-31', 1, 565, 550, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario ING de los pisos del 1º (may 2021 - ago 2026). Alquiler de 550 € hasta enero de 2024 y de 565 € desde febrero de 2024. Agosto de 2022 y junio de 2023 sin transferencia. Fianza 550 € ingresada en el IGVS el 16/08/2022 y devuelta por el IGVS el 05/11/2025. Seguro de impago DAS contratado el 11/08/2022.'),
(33, 'RNT-2025-033', 5, 33, NULL, '2025-11-24', NULL, 1, 585, 585, FALSE, 'ACTIVE', TRUE, 'Importado del extracto bancario ING de los pisos del 1º (may 2021 - ago 2026). Noviembre de 2025 prorrateado (97 €). Fianza no localizada en el extracto (pendiente de confirmar); el 18/12/2025 salió un traspaso interno «Fianza 1 drta» de 565 €.'),
(34, 'RNT-2021-034', 6, 34, NULL, '2021-07-01', '2024-02-29', 1, 525, 1000, TRUE, 'TERMINATED', FALSE, 'Importado del extracto bancario ING de los pisos del 1º (may 2021 - ago 2026). Alquiler de 500 € hasta diciembre de 2022, 510 € en 2023 y 525 € desde enero de 2024. Fianza 500 € ingresada en la Xunta (IGVS) el 09/07/2021 y devuelta por el IGVS el 12/03/2024; el 21/03/2024 se le devolvieron 900 € (fianzas menos pintura y limpieza). El ingreso duplicado de 510 € del 06/01/2024 se le devolvió el mismo día y no se contabiliza.'),
(35, 'RNT-2024-035', 6, 35, NULL, '2024-04-01', NULL, 1, 625, 1250, TRUE, 'ACTIVE', TRUE, 'Importado del extracto bancario ING de los pisos del 1º (may 2021 - ago 2026). Transferencias del 21/03/2024: fianza 625 € + garantía 625 € + 175 € (su mitad del seguro de impago DAS, no contabilizado como alquiler).');
